import React, {useState} from 'react'
import './App.css';
import {BrowserRouter as Router, Switch, Route, Redirect} from "react-router-dom";
import professorList from './json/professorsList.json'
import professorNisoli from './json/Nisoli-Mauro.json'
import professorAbastante from './json/Abastante-Francesca.json'
//Pages
import Home from './pages/Home.js'
import NotFoundPage from './pages/404'
import Professor from "./pages/Professor";


function App() {

  let [professor, setProfessor] = useState("");


  if(setProfessor != null){
      console.log(professor);
      if (professor === professorAbastante.endpoint){
          professor = professorAbastante
      }
      else {
          professor=professorNisoli;
      }

  }

  return (
      <Router>
        <Switch>
          <Route path='/' exact component={() => <Home professorList={professorList} onChangeProfessor={setProfessor} isHome={true}/>}/>
          <Route path='/404' exact component={NotFoundPage}/>
          <Route path="/professors/:endpoint" exact component={() => <Professor isHome={false} endpoint={professor.endpoint} professorList={professorList} onChangeProfessor={setProfessor} professor={professor} />} />
          <Redirect to="/404"/>
        </Switch>
      </Router>
  );
}

export default App;
